        for(var e:types.entrySet()){
            column(e.getKey());require(!Set.of("cell_id","f_expression","Size_Factor","cluster","partition","pseudotime").contains(e.getKey()),"Reserved original metadata column: "+e.getKey());var spec=object(e.getValue());allowed(spec,"type","levels");String type=text(spec.get("type"));require(Set.of("numeric","factor").contains(type),"Choose numeric or factor metadata");if(type.equals("factor"))labels(spec.get("levels"),1000000);else require(!spec.containsKey("levels"),"Numeric metadata has no factor levels");
        }
        var preprocessing=object(m.get("preprocessing"));allowed(preprocessing,"method","num_dim","norm_method","scaling","pseudo_count");require(Set.of("PCA","LSI").contains(text(preprocessing.get("method"))),"Original preprocessing method must be PCA or LSI");integer(preprocessing.get("num_dim"),2,1024);require(Set.of("log","size_only","none").contains(text(preprocessing.get("norm_method"))),"Declare original normalization log, size_only or none");bool(preprocessing.get("scaling"));if(preprocessing.containsKey("pseudo_count"))require("ORIGINAL_DEFAULT".equals(preprocessing.get("pseudo_count"))||finite(preprocessing.get("pseudo_count"))>=0,"Pseudo-count must be nonnegative or ORIGINAL_DEFAULT");
