        var reduction=object(m.get("reduction"));allowed(reduction,"max_components","n_neighbors","min_dist","metric","fast_sgd");integer(reduction.get("max_components"),2,1024);integer(reduction.get("n_neighbors"),2,1000000);require(finite(reduction.get("min_dist"))>=0,"UMAP min_dist must be nonnegative");require(Set.of("cosine","euclidean","manhattan").contains(text(reduction.get("metric"))),"Choose a supported original UMAP metric");bool(reduction.get("fast_sgd"));
        var clustering=object(m.get("clustering"));allowed(clustering,"method","k","num_iter","partition_qval","weight","resolution","random_seed");require(Set.of("leiden","louvain").contains(text(clustering.get("method"))),"Declare original leiden or louvain clustering");integer(clustering.get("k"),1,1000000);integer(clustering.get("num_iter"),1,1000000);double q=finite(clustering.get("partition_qval"));require(q>=0&&q<=1,"Partition q threshold outside [0,1]");bool(clustering.get("weight"));if(clustering.get("resolution")!=null)require(finite(clustering.get("resolution"))>0,"Clustering resolution must be positive or null for original selection");integer(clustering.get("random_seed"),1,2147483646);
        var graph=object(m.get("graph"));allowed(graph,"use_partition","close_loop","ncenter","minimal_branch_len");bool(graph.get("use_partition"));bool(graph.get("close_loop"));if(!"ORIGINAL_DEFAULT".equals(graph.get("ncenter")))integer(graph.get("ncenter"),2,1000000);if(!"ORIGINAL_DEFAULT".equals(graph.get("minimal_branch_len")))integer(graph.get("minimal_branch_len"),0,1000000);
        bool(m.get("require_terminal_roots"));boolean principal=m.containsKey("root_pr_nodes"),cells=m.containsKey("root_cells");if(mode.equals("RUN")){require(principal!=cells,"RUN requires exactly one explicit root_pr_nodes or root_cells declaration");labels(m.get(principal?"root_pr_nodes":"root_cells"),1000000);}else require(!principal&&!cells,"LEARN accepts no roots and admits no pseudotime");
        if(m.containsKey("expected_principal_graph_sha256"))require(text(m.get("expected_principal_graph_sha256")).matches("[0-9a-f]{64}"),"Expected graph identity must be lowercase SHA256");
        var libraries=new ArrayList<Path>();for(Object x:list(m.get("r_libraries"))){require(libraries.size()<16,"Too many declared R libraries");libraries.add(path(parent,x));}require(!libraries.isEmpty(),"Declare private R libraries");String policy=text(m.get("execution_policy"));require(Set.of("ALLOW","FORBID").contains(policy),"Declare execution policy ALLOW or FORBID");
